style.css:
@-moz-document domain("youtube.com") {
/* Progress bar height */
    .ytp-progress-bar-container {
        height: 10px !important;
    }

    /* The empty/background part of the bar */
    .ytp-progress-bar {
        background-image: url("https://t4.ftcdn.net/jpg/08/96/61/93/360_F_896619380_7dFwpNM824vtv9Qx4Au2xusymHpJcqaD.jpg") !important;
        background-size: cover !important;
        background-position: center !important;
        border-radius: 10px !important;
    }

    /* The part that has already played */
    .ytp-play-progress {
        background-image: url("https://t4.ftcdn.net/jpg/08/96/61/93/360_F_896619380_7dFwpNM824vtv9Qx4Au2xusymHpJcqaD.jpg") !important;
        background-size: cover !important;
        background-position: center !important;

        box-shadow:
            0 0 8px white,
            0 0 15px #ff8cff !important;

        border-radius: 10px !important;
    }

    /* Buffering section */
    .ytp-load-progress {
        background: rgba(255,255,255,0.25) !important;
    }

    /* Hover preview */
    .ytp-hover-progress {
        background-image: url("https://t4.ftcdn.net/jpg/08/96/61/93/360_F_896619380_7dFwpNM824vtv9Qx4Au2xusymHpJcqaD.jpg") !important;
        background-size: cover !important;
    }


    /* ==========================
       CUSTOM IMAGE AT BAR END
       ========================== */

    .ytp-scrubber-button {
        width: 38px !important;
        height: 38px !important;

        background-image: url("https://d2bzx2vuetkzse.cloudfront.net/fit-in/0x450/images_without_background/b0d20017-c15e-4bca-b5a8-2afe50794188.png") !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;

        background-color: transparent !important;
        border: none !important;

        filter:
            drop-shadow(0 0 6px #ff7bf7)
            drop-shadow(0 0 10px #7df9ff) !important;
    }

    /* Remove YouTube's default circle */
    .ytp-scrubber-button svg {
        display: none !important;
    }
}
